func main() {
	node := maelstrom.NewNode()
	defer node.Close()

	// Handle init message to get node ID
	node.Handle(maelstrom.InitMsg{}) = func(ctx *maelstrom.Context, msg *maelstrom.Msg) (bool, error) {
		// Just acknowledge init
		return false, nil
	}

	// Handle generate requests
	node.Handle(maelstrom.Msg{Type: "generate"}) = func(ctx *maelstrom.Context, msg *maelstrom.Msg) (bool, error) {
		// Read counter from disk atomically
		counter := readCounter(ctx.NodeID)

		// Increment and write back
		counter++
		writeCounter(ctx.NodeID, counter)

		reply := map[string]interface{}{
			"type":           "generate_ok",
			"in_reply_to":    msg.ID,
			"id":             fmt.Sprintf("%s-%d", ctx.NodeID, counter),
		}

		err := ctx.Reply(reply)
		if err != nil {
			return false, err
		}

		return true, nil
	}

	node.Run()
}

