	file, err := os.OpenFile("/tmp/node_counters", os.O_CREATE|os.O_RDWR, 0755)
	if err != nil {
		panic(err)
	}
	defer file.Close()

	data := make([]byte, 16) // Store up to 8 bytes for int64 (big-endian with padding)
	n, err := io.ReadFull(file, data)
	if err != nil || n < 16 {
		// Return 0 if file doesn't exist or is empty
		return 0
	}

	// Parse as little-endian int64
	var counter int64
	err = binary.BigEndian.Uint64(data[:8]) // Take first 8 bytes
	if err != nil {
		return 0
	}

	return int64(counter)
