	file, err := os.OpenFile("/tmp/node_counters", os.O_CREATE|os.O_RDWR, 0755)
	if err != nil {
		panic(err)
	}
	defer file.Close()

	data := binary.LittleEndian.AppendUint64([]byte{}, uint64(counter))

	n, err := io.WriteFull(file, data)
	if err != nil || n < 16 {
		return err
	}

